#include "tangra_fc/mission_protocol.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
namespace tangra::fc {
MissionAck MissionProtocolEndpoint::receive(const MissionGoalCommand&c,std::uint64_t now,MissionStateWire state){MissionAck a{};a.sequence=c.sequence;a.mission_state=state;if(c.protocol_version!=kMissionProtocolVersion){a.status=ProtocolStatus::VersionMismatch;a.fault=MissionFault::Protocol;return a;}if(!connected_||!synchronized_){a.status=ProtocolStatus::NotSynchronized;a.fault=MissionFault::LinkLoss;return a;}if(!c.valid||c.ttl_ms==0||!std::isfinite(c.x)||!std::isfinite(c.y)||!std::isfinite(c.z)){a.status=ProtocolStatus::Rejected;a.fault=MissionFault::InvalidGoal;return a;}if(now<c.timestamp_ms||now-c.timestamp_ms>c.ttl_ms){a.status=ProtocolStatus::Stale;return a;}if(has_sequence_&&c.sequence<=last_sequence_){a.status=ProtocolStatus::OutOfOrder;return a;}if(!sink_.accept_goal(c)){a.status=ProtocolStatus::Rejected;a.fault=MissionFault::NotReady;return a;}last_sequence_=c.sequence;has_sequence_=true;a.status=ProtocolStatus::Accepted;return a;}
void MissionProtocolEndpoint::on_disconnect(){connected_=false;synchronized_=false;}
void MissionProtocolEndpoint::on_reconnect(){connected_=true;synchronized_=false;}
void MissionProtocolEndpoint::resynchronize(std::uint64_t peer_last){if(connected_){if(!has_sequence_||peer_last>=last_sequence_){last_sequence_=peer_last;has_sequence_=true;}synchronized_=true;}}
MissionTelemetry MissionProtocolEndpoint::telemetry(MissionStateWire s,double p,MissionFault f)const{MissionTelemetry t;t.last_accepted_sequence=last_sequence_;t.mission_state=s;t.progress=std::max(0.0,std::min(1.0,p));t.fault=f;t.synchronized=synchronized_&&connected_;return t;}
namespace{
template<class T>void put(std::vector<std::uint8_t>&p,T v){std::uint8_t raw[sizeof(T)];std::memcpy(raw,&v,sizeof(T));p.insert(p.end(),raw,raw+sizeof(T));}
template<class T>bool get(const std::vector<std::uint8_t>&p,std::size_t&off,T&v){if(off+sizeof(T)>p.size())return false;std::memcpy(&v,p.data()+off,sizeof(T));off+=sizeof(T);return true;}
bool valid_protocol_status(std::uint8_t v){return v<=static_cast<std::uint8_t>(ProtocolStatus::NotSynchronized);}
bool valid_state(std::uint8_t v){return v<=static_cast<std::uint8_t>(MissionStateWire::FAULT);}
bool valid_fault(std::uint16_t v){return v<=static_cast<std::uint16_t>(MissionFault::NotReady);}
}
std::vector<std::uint8_t>MissionPayloadCodec::encode_goal(const MissionGoalCommand&c){std::vector<std::uint8_t>p;p.reserve(kGoalPayloadLength);put(p,c.protocol_version);put(p,c.sequence);put(p,c.timestamp_ms);put(p,c.ttl_ms);put(p,c.x);put(p,c.y);put(p,c.z);put<std::uint8_t>(p,c.valid?1:0);return p;}
std::optional<MissionGoalCommand>MissionPayloadCodec::decode_goal(const std::vector<std::uint8_t>&p){if(p.size()!=kGoalPayloadLength)return std::nullopt;MissionGoalCommand c{};std::size_t o=0;std::uint8_t valid=0;if(!get(p,o,c.protocol_version)||!get(p,o,c.sequence)||!get(p,o,c.timestamp_ms)||!get(p,o,c.ttl_ms)||!get(p,o,c.x)||!get(p,o,c.y)||!get(p,o,c.z)||!get(p,o,valid)||o!=p.size()||valid>1)return std::nullopt;c.valid=valid!=0;return c;}
std::vector<std::uint8_t>MissionPayloadCodec::encode_ack(const MissionAck&a){std::vector<std::uint8_t>p;p.reserve(kAckPayloadLength);put(p,a.sequence);put<std::uint8_t>(p,static_cast<std::uint8_t>(a.status));put<std::uint8_t>(p,static_cast<std::uint8_t>(a.mission_state));put<std::uint16_t>(p,static_cast<std::uint16_t>(a.fault));return p;}
std::optional<MissionAck>MissionPayloadCodec::decode_ack(const std::vector<std::uint8_t>&p){if(p.size()!=kAckPayloadLength)return std::nullopt;MissionAck a{};std::size_t o=0;std::uint8_t st=0,ms=0;std::uint16_t f=0;if(!get(p,o,a.sequence)||!get(p,o,st)||!get(p,o,ms)||!get(p,o,f)||o!=p.size()||!valid_protocol_status(st)||!valid_state(ms)||!valid_fault(f))return std::nullopt;a.status=static_cast<ProtocolStatus>(st);a.mission_state=static_cast<MissionStateWire>(ms);a.fault=static_cast<MissionFault>(f);return a;}
std::vector<std::uint8_t>MissionPayloadCodec::encode_telemetry(const MissionTelemetry&t){std::vector<std::uint8_t>p;p.reserve(kTelemetryPayloadLength);put(p,t.capability_version);put(p,t.last_accepted_sequence);put<std::uint8_t>(p,static_cast<std::uint8_t>(t.mission_state));put(p,t.progress);put<std::uint16_t>(p,static_cast<std::uint16_t>(t.fault));put<std::uint8_t>(p,t.synchronized?1:0);return p;}
std::optional<MissionTelemetry>MissionPayloadCodec::decode_telemetry(const std::vector<std::uint8_t>&p){if(p.size()!=kTelemetryPayloadLength)return std::nullopt;MissionTelemetry t{};std::size_t o=0;std::uint8_t ms=0,sync=0;std::uint16_t f=0;if(!get(p,o,t.capability_version)||!get(p,o,t.last_accepted_sequence)||!get(p,o,ms)||!get(p,o,t.progress)||!get(p,o,f)||!get(p,o,sync)||o!=p.size()||!valid_state(ms)||!valid_fault(f)||sync>1||!std::isfinite(t.progress))return std::nullopt;t.mission_state=static_cast<MissionStateWire>(ms);t.fault=static_cast<MissionFault>(f);t.synchronized=sync!=0;return t;}
bool MavlinkMissionDialectContract::valid()const{return goal.message_id!=0&&ack.message_id!=0&&telemetry.message_id!=0&&goal.message_id!=ack.message_id&&goal.message_id!=telemetry.message_id&&ack.message_id!=telemetry.message_id&&goal.payload_length==MissionPayloadCodec::kGoalPayloadLength&&ack.payload_length==MissionPayloadCodec::kAckPayloadLength&&telemetry.payload_length==MissionPayloadCodec::kTelemetryPayloadLength;}
std::optional<MavlinkPayloadEnvelope>MavlinkMissionPayloadAdapter::encode_goal(const MissionGoalCommand&v)const{if(!configured())return std::nullopt;return MavlinkPayloadEnvelope{contract_.goal.message_id,MissionPayloadCodec::encode_goal(v)};}
MavlinkDecodeResult<MissionGoalCommand>MavlinkMissionPayloadAdapter::decode_goal(const MavlinkPayloadEnvelope&m)const{if(!configured())return{MavlinkAdapterStatus::DialectUnavailable,{}};if(m.message_id!=contract_.goal.message_id)return{MavlinkAdapterStatus::UnknownMessageId,{}};if(m.payload.size()!=contract_.goal.payload_length)return{MavlinkAdapterStatus::MalformedLength,{}};auto v=MissionPayloadCodec::decode_goal(m.payload);return v?MavlinkDecodeResult<MissionGoalCommand>{MavlinkAdapterStatus::Ok,v}:MavlinkDecodeResult<MissionGoalCommand>{MavlinkAdapterStatus::InvalidPayload,{}};}
std::optional<MavlinkPayloadEnvelope>MavlinkMissionPayloadAdapter::encode_ack(const MissionAck&v)const{if(!configured())return std::nullopt;return MavlinkPayloadEnvelope{contract_.ack.message_id,MissionPayloadCodec::encode_ack(v)};}
MavlinkDecodeResult<MissionAck>MavlinkMissionPayloadAdapter::decode_ack(const MavlinkPayloadEnvelope&m)const{if(!configured())return{MavlinkAdapterStatus::DialectUnavailable,{}};if(m.message_id!=contract_.ack.message_id)return{MavlinkAdapterStatus::UnknownMessageId,{}};if(m.payload.size()!=contract_.ack.payload_length)return{MavlinkAdapterStatus::MalformedLength,{}};auto v=MissionPayloadCodec::decode_ack(m.payload);return v?MavlinkDecodeResult<MissionAck>{MavlinkAdapterStatus::Ok,v}:MavlinkDecodeResult<MissionAck>{MavlinkAdapterStatus::InvalidPayload,{}};}
std::optional<MavlinkPayloadEnvelope>MavlinkMissionPayloadAdapter::encode_telemetry(const MissionTelemetry&v)const{if(!configured())return std::nullopt;return MavlinkPayloadEnvelope{contract_.telemetry.message_id,MissionPayloadCodec::encode_telemetry(v)};}
MavlinkDecodeResult<MissionTelemetry>MavlinkMissionPayloadAdapter::decode_telemetry(const MavlinkPayloadEnvelope&m)const{if(!configured())return{MavlinkAdapterStatus::DialectUnavailable,{}};if(m.message_id!=contract_.telemetry.message_id)return{MavlinkAdapterStatus::UnknownMessageId,{}};if(m.payload.size()!=contract_.telemetry.payload_length)return{MavlinkAdapterStatus::MalformedLength,{}};auto v=MissionPayloadCodec::decode_telemetry(m.payload);return v?MavlinkDecodeResult<MissionTelemetry>{MavlinkAdapterStatus::Ok,v}:MavlinkDecodeResult<MissionTelemetry>{MavlinkAdapterStatus::InvalidPayload,{}};}
std::optional<std::uint8_t>MavlinkMissionPayloadAdapter::crc_extra_for(std::uint32_t id)const{if(!configured())return std::nullopt;if(id==contract_.goal.message_id)return contract_.goal.crc_extra;if(id==contract_.ack.message_id)return contract_.ack.crc_extra;if(id==contract_.telemetry.message_id)return contract_.telemetry.crc_extra;return std::nullopt;}
}
